 out=O/(name+'.stdout');err=O/(name+'.stderr');out.parent.mkdir(parents=True,exist_ok=True)
 with out.open('wb') as a,err.open('wb') as b:
  p=subprocess.run(args,cwd=cwd,env=env,stdout=a,stderr=b,timeout=min(timeout,max(1,6850-(time.monotonic()-START))))
 save(O/(name+'.json'),{'argv':args,'exit_status':p.returncode,'stdout_sha256':sha(out.read_bytes()),'stderr_sha256':sha(err.read_bytes())});print(name,p.returncode,flush=True)
 if (pathlib.Path(cwd)/'Cargo.lock').is_file():assert sha((pathlib.Path(cwd)/'Cargo.lock').read_bytes())==PLAN['expected_producer_lock_sha256'],'Command mutated pinned dependency lock: '+name
 if len(args)>1 and args[0]=='cargo' and args[1]=='test':retain_executed_test_binaries(name,err.read_text())
 if required:assert p.returncode==0,name
 return p.returncode
